let sentence = "She gave her mother a handmade card."
let prepositions = ["to", "for", "with", "on", "in", "at", "from", "by", "about", "of", "over", "under"]
func identifyObjects(in sentence: String) {
    let words = sentence.components(separatedBy: " ")
    var preposition: String?
    var indirectObject: String?
    var directObject: String?

    for i in 0..<words.count {
        let word = words[i]
        if prepositions.contains(word) {
            preposition = word
        } else if i > 0 && preposition != nil && indirectObject == nil {
            indirectObject = words[i-1]
        } else if i < words.count-1 && preposition != nil && directObject == nil {
            directObject = words[i+1]
        }
    }

    print("Preposition: \(preposition ?? "N/A")")
    print("Indirect Object: \(indirectObject ?? "N/A")")
    print("Direct Object: \(directObject ?? "N/A")")
}
identifyObjects(in: sentence)
```
