```java
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.Scanner;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
public class PerceptionSimulation {

  public static void main(String[] args) {
    List<Perception> perceptions = parseXML("perceptions.xml");
    Scanner scanner = new Scanner(System.in);
    Random random = new Random();

    // Get user input for cultural and societal norms
    System.out.print("Enter your cultural norm (1-5): ");
    int culturalNorm = scanner.nextInt();
    System.out.print("Enter your societal norm (1-5): ");
    int societalNorm = scanner.nextInt();

    // Generate random desires for each perception
    for (Perception perception : perceptions) {
      int desire = random.nextInt(5) + 1;
      perception.setDesire(desire);

      // Apply cultural and societal norms to desire
      if (perception.getInfluence().equals("Cultural")) {
        perception.setDesire(perception.getDesire() + culturalNorm);
      } else if (perception.getInfluence().equals("Societal")) {
        perception.setDesire(perception.getDesire() + societalNorm);
      }
    }

    // Compare two perceptions and determine which one is "greener"
    Perception p1 = perceptions.get(random.nextInt(perceptions.size()));
    Perception p2 = perceptions.get(random.nextInt(perceptions.size()));
    while (p1.equals(p2)) {
      p2 = perceptions.get(random.nextInt(perceptions.size()));
    }
    int result = compareSatisfaction(p1, p2);
    String greener = result > 0 ? p1.getName() : p2.getName();
    System.out.printf("The grass is greener on the %s side.%n", greener.toLowerCase());
  }

  private static List<Perception> parseXML(String filename) {
    List<Perception> perceptions = new ArrayList<>();
    try {
      DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
      DocumentBuilder builder = factory.newDocumentBuilder();
      Document doc = builder.parse(filename);
      NodeList nodes = doc.getElementsByTagName("perception");
      for (int i = 0; i < nodes.getLength(); i++) {
        Element element = (Element) nodes.item(i);
        Perception perception = new Perception();
        perception.setName(element.getElementsByTagName("name").item(0).getTextContent());
        perception.setInfluence(element.getElementsByTagName("influence").item(0).getTextContent());
        perception.setSatisfaction(element.getElementsByTagName("satisfaction").item(0).getTextContent());
        perceptions.add(perception);
      }
    } catch (Exception e) {
      e.printStackTrace();
    }
    return perceptions;
  }

  private static int compareSatisfaction(Perception p1, Perception p2) {
    return p1.getSatisfaction().compareTo(p2.getSatisfaction());
  }

}
class Perception {
  private String name;
  private int desire;
  private String influence;
  private String satisfaction;

  public String getName() {
    return name;
  }

  public void setName(String name) {
    this.name = name;
  }

  public int getDesire() {
    return desire;
  }

  public void setDesire(int desire) {
    this.desire = desire;
  }

  public String getInfluence() {
    return influence;
  }

  public void setInfluence(String influence) {
    this.influence = influence;
  }

  public String getSatisfaction() {
    return satisfaction;
  }

  public void setSatisfaction(String satisfaction) {
    this.satisfaction = satisfaction;
  }

  @Override
  public boolean equals(Object obj) {
    if (obj == this) {
      return true;
    }
    if (!(obj instanceof Perception)) {
      return false;
    }
    Perception other = (Perception) obj;
    return this.name.equals(other.name);
  }
}
