    for {
        randomField = fieldsOfStudy[rand.Intn(len(fieldsOfStudy))]
        for _, v := range vowels {
            if string(randomField[0]) == v {
                return fmt.Sprintf("%s %s %s", randomVowel, randomField, randomSynonym)
            }
        }
    }
}
