func isAnagramAndPalindrome(_ str1: String, _ str2: String) -> Bool {
    // check if the two strings have the same length
    guard str1.count == str2.count else {
        return false
    }

    // check if they are anagrams
    let charCount1 = str1.reduce(into: [:]) { counts, char in
        counts[char, default: 0] += 1
    }
    let charCount2 = str2.reduce(into: [:]) { counts, char in
        counts[char, default: 0] += 1
    }
    guard charCount1 == charCount2 else {
        return false
    }

    // check if the first string is a palindrome
    let reversedStr1 = String(str1.reversed())
    return str1 == reversedStr1
}
