Sure, here's a sample C++ code that generates a set of 10 unique random numbers between 1 and 10 and sorts them in ascending order:
```c++
#include <iostream>
#include <algorithm>
#include <vector>
#include <random>
int main()
{
    std::vector<int> nums;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 10);
    while (nums.size() < 10) {
        int num = dis(gen);
        if (std::find(nums.begin(), nums.end(), num) == nums.end()) {
            nums.push_back(num);
        }
    }
    std::sort(nums.begin(), nums.end());
    for (auto num : nums) {
        std::cout << num << " ";
    }
    std::cout << std::endl;
    return 0;
}
```
