      // Modify code to expand reach, improve engagement and satisfaction, and stay competitive
      val modifiedMarketingStrategy = if (opportunities.contains("social media")) {
        "Utilize social media platforms to engage with potential and current students, share success stories and testimonials, and offer exclusive promotions and discounts."
