```python
import cv2
face_cascade = cv2.CascadeClassifier("haarcascade_frontalface_default.xml")
mask_cascade = cv2.CascadeClassifier("haarcascade_mask.xml")
def detect_mask(image):
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, 1.1, 4)

    for (x, y, w, h) in faces:
        roi_gray = gray[y:y+h, x:x+w]
        roi_color = image[y:y+h, x:x+w]
        masks = mask_cascade.detectMultiScale(roi_gray, 1.1, 4)

        if len(masks) == 0:
            cv2.rectangle(image, (x, y), (x+w, y+h), (0, 0, 255), 2)
            cv2.putText(image, "No Mask", (x, y-10), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 0, 255), 2)
        else:
            cv2.rectangle(image, (x, y), (x+w, y+h), (0, 255, 0), 2)
            cv2.putText(image, "Mask", (x, y-10), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 255, 0), 2)

    return image
image = cv2.imread("people.jpg")
result = detect_mask(image)
cv2.imshow("Result", result)
cv2.waitKey(0)
cv2.destroyAllWindows()
```
