Yes, I am up for the challenge. Here's a Python program that models the natural selection process in this world:
```python
import random
class Animal:
    def __init__(self, species):
        self.species = species
        self.fitness = 1.0
    def __repr__(self):
        return f"{self.species} ({self.fitness:.2f})"
class Environment:
    def __init__(self, food, predators):
        self.food = food
        self.predators = predators
    def __repr__(self):
        return f"Food: {self.food}, Predators: {self.predators}"
    def get_fitness(self, animal):
        if animal.species == "rabbit":
            return self.food * animal.fitness
        elif animal.species == "wolf":
            return (self.food * animal.fitness) - (self.predators * animal.fitness)
        elif animal.species == "bear":
            return (self.food * animal.fitness) - (self.predators * animal.fitness * 2)
    def select_animal(self, population):
        fitnesses = [self.get_fitness(animal) for animal in population]
        total_fitness = sum(fitnesses)
        probabilities = [fitness / total_fitness for fitness in fitnesses]
        return random.choices(population, probabilities)[0]
class World:
    def __init__(self, num_rabbits, num_wolves, num_bears):
        self.num_rabbits = num_rabbits
        self.num_wolves = num_wolves
        self.num_bears = num_bears
        self.year = 0
        self.environment = Environment(1.0, 0.0)
    def simulate_year(self):
        self.year += 1
        self.environment.food = random.uniform(0.5, 1.5)
        self.environment.predators = random.uniform(0.0, 0.5)
        population = []
        for i in range(self.num_rabbits):
            population.append(Animal("rabbit"))
        for i in range(self.num_wolves):
            population.append(Animal("wolf"))
        for i in range(self.num_bears):
            population.append(Animal("bear"))
        for animal in population:
            animal.fitness = self.environment.get_fitness(animal)
        new_population = []
        while len(new_population) < len(population):
            parent1 = self.environment.select_animal(population)
            parent2 = self.environment.select_animal(population)
            child = Animal(parent1.species)
            if random.random() < 0.5:
                child.fitness = (parent1.fitness + parent2.fitness) / 2
            else:
                child.fitness = random.uniform(min(parent1.fitness, parent2.fitness), max(parent1.fitness, parent2.fitness))
            new_population.append(child)
        self.num_rabbits = 0
        self.num_wolves = 0
        self.num_bears = 0
        for animal in new_population:
            if animal.species == "rabbit":
                self.num_rabbits += 1
            elif animal.species == "wolf":
                self.num_wolves += 1
            elif animal.species == "bear":
                self.num_bears += 1
    def run_simulation(self, num_years):
        print(f"Year 0: {self.num_rabbits} rabbits, {self.num_wolves} wolves, {self.num_bears} bears")
        for i in range(num_years):
            self.simulate_year()
            print(f"Year {self.year}: {self.num_rabbits} rabbits, {self.num_wolves} wolves, {self.num_bears} bears")
world = World(100, 20, 5)
world.run_simulation(10)
```
The program simulates a world with 100 rabbits, 20 wolves, and 5 bears. Each year, the environment changes randomly, affecting the availability of food and the number of predators. The fitness of each animal is calculated based on their species and the current environment. The program then uses a selection algorithm to choose parents for the next generation, taking into account their fitness. The offspring inherit traits from their parents, with some random variation. The program tracks the number of animals of each species over time, and shows how their fitness changes based on the environment.

To calculate the minimum score the student needs to achieve on the next exam, we can use the following formula:
minimum score = (desired grade - (1 - exam weight) * initial score) / exam weight
Here, the desired grade is 80%, the exam weight is 40%, and the initial score is the student's current grade before the next exam.
Here's a code snippet that demonstrates how this calculation can be performed in C++:
```
#include <iostream>
using namespace std;
int main() {
    double initialScore, examWeight, desiredGrade, minimumScore;
    cout << "Enter initial score: ";
    cin >> initialScore;
    cout << "Enter exam weight: ";
    cin >> examWeight;
    cout << "Enter desired grade: ";
    cin >> desiredGrade;
    minimumScore = (desiredGrade - (1 - examWeight) * initialScore) / examWeight;
    cout << "The minimum score required on the next exam is: " << minimumScore << endl;
    return 0;
}
```
This program prompts the user to enter the initial score, exam weight, and desired grade, and then calculates the minimum score required on the next exam using the formula above. The result is then displayed to the user.
